// See defs.go for other definitions

import "fmt"

// Step 1
// Define N, E, S, W here.

const (
	N Dir = iota
	E
	S
	W
)

func turnRight(d Dir) Dir { return (d + 1) % 4 }
func turnLeft(d Dir) Dir  { return (d + 3) % 4 }

func Right() {
	Step1Robot.Dir = turnRight(Step1Robot.Dir)
}

func Left() {
	Step1Robot.Dir = turnLeft(Step1Robot.Dir)
}

func Advance() {
	switch Step1Robot.Dir {
	case N:
		Step1Robot.Y++
	case S:
		Step1Robot.Y--
	case E:
		Step1Robot.X++
	case W:
		Step1Robot.X--
	}
}

func (d Dir) String() string {
	switch d {
	case N:
		return "North"
	case E:
		return "East"
	case S:
		return "South"
	case W:
		return "West"
	}
	return "Unknown"
}

// inRect reports whether p is within the closed rectangle extent.
func inRect(extent Rect, p Pos) bool {
	return p.Easting >= extent.Min.Easting && p.Easting <= extent.Max.Easting &&
		p.Northing >= extent.Min.Northing && p.Northing <= extent.Max.Northing
}

// advancePos returns the position one step ahead of p in direction d.
func advancePos(p Pos, d Dir) Pos {
	switch d {
	case N:
		p.Northing++
	case S:
		p.Northing--
	case E:
		p.Easting++
	case W:
		p.Easting--
	}
	return p
}

// Step 2
// Define Action type here.

type Action Command

func StartRobot(command chan Command, action chan Action) {
	for cmd := range command {
		action <- Action(cmd)
	}
	close(action)
}

func Room(extent Rect, robot Step2Robot, action chan Action, report chan Step2Robot) {
	for act := range action {
		switch Command(act) {
		case 'R':
			robot.Dir = turnRight(robot.Dir)
		case 'L':
			robot.Dir = turnLeft(robot.Dir)
		case 'A':
			np := advancePos(robot.Pos, robot.Dir)
			if inRect(extent, np) {
				robot.Pos = np
			}
		}
	}
	report <- robot
}

// Step 3
// Define Action3 type here.

// Action3 carries a command from a named robot to the room.  A Cmd of 0
// signals that the named robot has finished its script.
type Action3 struct {
	Name string
	Cmd  byte
}

func StartRobot3(name, script string, action chan Action3, log chan string) {
	for i := 0; i < len(script); i++ {
		c := script[i]
		switch c {
		case 'A', 'R', 'L':
			action <- Action3{name, c}
		default:
			log <- fmt.Sprintf("robot %q: undefined command %q in script", name, c)
			action <- Action3{name, 0}
			return
		}
	}
	action <- Action3{name, 0}
}

func Room3(extent Rect, robots []Step3Robot, action chan Action3, rep chan []Step3Robot, log chan string) {
	seenName := map[string]bool{}
	seenPos := map[Pos]bool{}
	for _, r := range robots {
		if r.Name == "" {
			log <- "a robot has no name"
		}
		if seenName[r.Name] {
			log <- fmt.Sprintf("duplicate robot name %q", r.Name)
		} else {
			seenName[r.Name] = true
		}
		if !inRect(extent, r.Pos) {
			log <- fmt.Sprintf("robot %q placed outside the room", r.Name)
		}
		if seenPos[r.Pos] {
			log <- fmt.Sprintf("robots placed at the same position %v", r.Pos)
		} else {
			seenPos[r.Pos] = true
		}
	}

	index := map[string]int{}
	for i, r := range robots {
		index[r.Name] = i
	}

	done := 0
	target := len(robots)
	for done < target {
		act := <-action
		if act.Cmd == 0 {
			done++
			continue
		}
		i, ok := index[act.Name]
		if !ok {
			log <- fmt.Sprintf("action from unknown robot %q", act.Name)
			continue
		}
		r := &robots[i]
		switch act.Cmd {
		case 'R':
			r.Dir = turnRight(r.Dir)
		case 'L':
			r.Dir = turnLeft(r.Dir)
		case 'A':
			np := advancePos(r.Pos, r.Dir)
			if !inRect(extent, np) {
				log <- fmt.Sprintf("robot %q attempted to advance into a wall", r.Name)
				continue
			}
			blocked := false
			for j, o := range robots {
				if j != i && o.Pos == np {
					blocked = true
					break
				}
			}
			if blocked {
				log <- fmt.Sprintf("robot %q attempted to advance into another robot", r.Name)
				continue
			}
			r.Pos = np
		}
	}
	rep <- robots
}
"}

